mapper.select:
SELECT v.id, v.driver_id, v.truck_type_id, v.license_plate_number, v.vehicle_brand, v.create_time, v.update_time, v.create_user, v.update_user, d.name AS driverName, tt.type_name AS truckTypeName, ca.name AS createUserName, ua.name AS updateUserName FROM vehicle v LEFT JOIN driver d ON v.driver_id = d.id LEFT JOIN truck_type tt ON v.truck_type_id = tt.id LEFT JOIN admin ca ON v.create_user = ca.id LEFT JOIN admin ua ON v.update_user = ua.id
AND v.license_plate_number LIKE CONCAT('%', #{licensePlateNumber}, '%')
AND v.driver_id = #{driverId}
AND v.truck_type_id = #{truckTypeId}
AND v.vehicle_brand LIKE CONCAT('%', #{vehicleBrand}, '%')
AND v.create_time >= #{createTimeStart}
AND v.create_time <= #{createTimeEnd}
ORDER BY v.create_time DESC

SELECT COUNT(*)
FROM vehicle
WHERE license_plate_number = #{licensePlateNumber}

    AND id != #{excludeId}

SELECT COUNT(*)
FROM vehicle
WHERE driver_id = #{driverId} AND truck_type_id = #{truckTypeId}

    AND id != #{excludeId}
